-- Name: can_user_action(bigint, character varying, bigint); Type: FUNCTION; Schema: access_control; Owner: ronald
--

CREATE FUNCTION access_control.can_user_action(p_id_user bigint, p_permission_key character varying, p_id_status bigint DEFAULT NULL::bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM access_control.user_role ur
        JOIN access_control.role_permission_by_status rps
            ON rps.id_role = ur.id_role
        WHERE ur.id_user    = p_id_user
          AND ur.is_active  = true
          AND rps.permission_key = p_permission_key
          AND rps.is_allowed     = true
          AND rps.is_active      = true
          AND (rps.id_status IS NULL OR rps.id_status = p_id_status)
    );
$$;


