--
-- Name: fn_update_article_counters(); Type: FUNCTION; Schema: knowledge_base; Owner: ronald
--

CREATE FUNCTION knowledge_base.fn_update_article_counters() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.is_helpful THEN
        UPDATE knowledge_base.kb_article
        SET helpful_count = helpful_count + 1
        WHERE id_article = NEW.id_article;
    ELSE
        UPDATE knowledge_base.kb_article
        SET not_helpful_count = not_helpful_count + 1
        WHERE id_article = NEW.id_article;
    END IF;
    RETURN NEW;
END;
$$;


