--
-- Name: search_articles(text, bigint, bigint, character varying, integer); Type: FUNCTION; Schema: knowledge_base; Owner: ronald
--

CREATE FUNCTION knowledge_base.search_articles(p_query text, p_id_user bigint DEFAULT NULL::bigint, p_id_cmpg bigint DEFAULT NULL::bigint, p_content_type character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 10) RETURNS TABLE(id_article bigint, title character varying, summary text, content_type character varying, category_name character varying, relevance real, is_pinned boolean, helpful_pct numeric)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        a.id_article,
        a.title,
        a.summary,
        a.content_type,
        c.name AS category_name,
        ts_rank(
            to_tsvector('spanish', a.title || ' ' || COALESCE(a.summary,'') || ' ' || a.content),
            plainto_tsquery('spanish', p_query)
        ) AS relevance,
        a.is_pinned,
        CASE
            WHEN (a.helpful_count + a.not_helpful_count) = 0 THEN NULL
            ELSE ROUND(100.0 * a.helpful_count / (a.helpful_count + a.not_helpful_count), 1)
        END AS helpful_pct
    FROM knowledge_base.kb_article a
    JOIN knowledge_base.kb_category c ON c.id_category = a.id_category
    WHERE a.is_published = true
      AND (a.deprecated_at IS NULL OR a.deprecated_at > CURRENT_TIMESTAMP)
      AND (p_id_cmpg IS NULL OR a.id_cmpg IS NULL OR a.id_cmpg = p_id_cmpg)
      AND (p_content_type IS NULL OR a.content_type = p_content_type)
      AND to_tsvector('spanish', a.title || ' ' || COALESCE(a.summary,'') || ' ' || a.content)
          @@ plainto_tsquery('spanish', p_query)
    ORDER BY a.is_pinned DESC, relevance DESC
    LIMIT p_limit;
$$;


