--
-- Name: convert_presale_to_order(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: lead_service; Owner: ronald
--

CREATE FUNCTION lead_service.convert_presale_to_order(p_id_presale bigint, p_id_cmpg bigint, p_id_user bigint, p_id_src bigint DEFAULT 1) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_presale   lead_service.lead_pre_sale%ROWTYPE;
    v_lead_id   BIGINT;
    v_order_id  BIGINT;
    v_status_id BIGINT;
BEGIN
    SELECT * INTO v_presale FROM lead_service.lead_pre_sale
    WHERE id_presale = p_id_presale AND id_status NOT IN (
        SELECT id_status FROM lead_service.pre_sale_status WHERE is_terminal = true
    );

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Pre-venta % no encontrada o ya cerrada', p_id_presale;
    END IF;

    -- Obtener status inicial de lead
    SELECT id_sts INTO v_status_id FROM lead_service.lead_status
    WHERE category = 'OPEN' ORDER BY order_index LIMIT 1;

    -- Crear el lead formal
    INSERT INTO lead_service.lead
        (id_cmpg, id_src, first_name, last_name, phone,
         raw_data, current_status_id, assigned_user_id, register)
    VALUES
        (p_id_cmpg, p_id_src, v_presale.first_name, v_presale.last_name,
         v_presale.phone,
         jsonb_build_object(
             'from_presale', p_id_presale,
             'operator', v_presale.operator,
             'address', v_presale.address,
             'province', v_presale.province,
             'tentative_offer', v_presale.tentative_offer
         ),
         v_status_id, p_id_user, CURRENT_TIMESTAMP)
    RETURNING id_lead INTO v_lead_id;

    -- Marcar pre-sale como convertido
    UPDATE lead_service.lead_pre_sale SET
        id_status            = (SELECT id_status FROM lead_service.pre_sale_status WHERE code = 'CONVERTIDO'),
        converted_to_order_id = v_lead_id,
        converted_at         = CURRENT_TIMESTAMP,
        converted_by         = p_id_user
    WHERE id_presale = p_id_presale;

    RETURN v_lead_id;
END;
$$;


ALTER FUNCTION lead_service.convert_presale_to_order(p_id_presale bigint, p_id_cmpg bigint, p_id_user bigint, p_id_src bigint) OWNER TO ronald;

--
-- Name: FUNCTION convert_presale_to_order(p_id_presale bigint, p_id_cmpg bigint, p_id_user bigint, p_id_src bigint); Type: COMMENT; Schema: lead_service; Owner: ronald
--

COMMENT ON FUNCTION lead_service.convert_presale_to_order(p_id_presale bigint, p_id_cmpg bigint, p_id_user bigint, p_id_src bigint) IS 'Convierte un pre-sale en un lead formal trayendo todos los datos
enriquecidos. Los datos del pre-sale viajan como raw_data para
que el asesor solo complete los campos faltantes.
Uso: SELECT lead_service.convert_presale_to_order(123, 5, 42, 1);';


--
-- Name: fn_log_lead_status_change(); Type: FUNCTION; Schema: lead_service; Owner: ronald
--

CREATE FUNCTION lead_service.fn_log_lead_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actor BIGINT;
BEGIN
    IF OLD.current_status_id IS DISTINCT FROM NEW.current_status_id THEN
        -- Intenta leer el usuario real de la sesión
        BEGIN
            v_actor := current_setting('app.current_user_id', true)::BIGINT;
        EXCEPTION WHEN OTHERS THEN
            v_actor := NEW.assigned_user_id;  -- fallback
        END;

        INSERT INTO lead_service.lead_tracking
            (id_lead, previous_status_id, new_status_id, id_user, comments, register)
        VALUES
            (NEW.id_lead, OLD.current_status_id, NEW.current_status_id,
             v_actor, 'Cambio de estado automático', CURRENT_TIMESTAMP);
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION lead_service.fn_log_lead_status_change() OWNER TO ronald;

