--
-- Name: fn_auto_notify_new_lead(); Type: FUNCTION; Schema: notification_service; Owner: ronald
--

CREATE FUNCTION notification_service.fn_auto_notify_new_lead() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec_user RECORD;
    v_full_name TEXT;
BEGIN
    -- 1. Obtener el nombre del postulante
    SELECT full_name INTO v_full_name 
    FROM recruitment_service.applicant 
    WHERE id_applc = NEW.id_applc;

    -- 2. Recorrer usuarios que tienen activas las notificaciones de RECLUTAMIENTO
    FOR rec_user IN 
        SELECT id_user, metadata 
        FROM notification_service.user_notification_config 
        WHERE module = 'RECLUTAMIENTO' 
          AND is_enabled = TRUE 
          AND notification_type = 'IN_APP'
    LOOP
        -- LÓGICA DE FILTRADO:
        -- Enviamos la alerta SI:
        -- A) El ID del usuario coincide con el reclutador que refirió al lead.
        -- B) El usuario tiene el rol de 'COORDINATOR' en su metadata.
        
        IF (rec_user.id_user = NEW.referred_by_id) OR (rec_user.metadata->>'role' = 'COORDINATOR') THEN
            
            INSERT INTO notification_service.user_alerts (id_user, title, message, module, action_data)
            VALUES (
                rec_user.id_user, 
                '🚀 ¡Nuevo Lead!', 
                'Un nuevo postulante ha ingresado: ' || COALESCE(v_full_name, 'Sin nombre'), 
                'RECLUTAMIENTO', 
                jsonb_build_object(
                    'id_applc', NEW.id_applc, 
                    'route', '/recruitment/leads',
                    'source', CASE WHEN rec_user.id_user = NEW.referred_by_id THEN 'DIRECT_REFERRAL' ELSE 'GENERAL_VIEW' END
                )
            );
            
        END IF;
    END LOOP;

    RETURN NEW;
END;
$$;


ALTER FUNCTION notification_service.fn_auto_notify_new_lead() OWNER TO ronald;

