--
-- Name: fn_log_ecosystem_trajectory(bigint, integer, text); Type: FUNCTION; Schema: recruitment_service; Owner: ronald
--

CREATE FUNCTION recruitment_service.fn_log_ecosystem_trajectory(p_related_id bigint, p_id_evty integer, p_related_table text DEFAULT 'job_application'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM ext_ecosystem.user_trajectory 
        WHERE id_evty = p_id_evty 
          AND related_id = p_related_id
          AND related_table = p_related_table
    ) THEN
        INSERT INTO ext_ecosystem.user_trajectory (
            id_user, id_evty, event_date, related_schema, related_table, related_id, state, register_at
        ) VALUES (
            NULL, p_id_evty, CURRENT_DATE, 'recruitment_service', p_related_table, p_related_id, true, now()
        );
    END IF;
EXCEPTION WHEN OTHERS THEN
    INSERT INTO recruitment_service.trajectory_sync_errors (id_applc, id_evty, error_message)
    VALUES (p_related_id, p_id_evty, 'Table: ' || p_related_table || ' - Error: ' || SQLERRM);
END;
$$;


ALTER FUNCTION recruitment_service.fn_log_ecosystem_trajectory(p_related_id bigint, p_id_evty integer, p_related_table text) OWNER TO ronald;

--
-- Name: trg_fn_log_apto_email(); Type: FUNCTION; Schema: recruitment_service; Owner: ronald
--

CREATE FUNCTION recruitment_service.trg_fn_log_apto_email() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Activamos solo cuando se registra el envío exitoso del correo
    IF (NEW.state = 2 AND 
        (OLD.metadata->'notifications'->>'entrevista_aprobada_mail') IS NULL AND 
        (NEW.metadata->'notifications'->>'entrevista_aprobada_mail') IS NOT NULL) THEN
        
        PERFORM recruitment_service.fn_log_ecosystem_trajectory(NEW.id_applc, 3);
    END IF;
    RETURN NEW;
END;
$$;


