COMMENT ON FUNCTION sales_service.validate_status_transition(p_from_status_id bigint, p_to_status_id bigint, p_role text) IS 'Valida si una transición de estado es permitida para un rol dado.
Uso: SELECT sales_service.validate_status_transition(3, 4, ''SUPERVISOR'');';


--
-- Name: fn_audit_trigger(); Type: FUNCTION; Schema: system_audit; Owner: ronald
--

CREATE FUNCTION system_audit.fn_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_old     jsonb;
    v_new     jsonb;
    v_id      text;
    v_user    text;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        v_old := to_jsonb(OLD);
        v_new := to_jsonb(NEW);
        IF v_old = v_new THEN RETURN NULL; END IF;
        -- Extraer PK: busca columna 'id' o la primera columna que empiece con 'id_'
        v_id := COALESCE(
            v_new->>'id',
            (SELECT value FROM jsonb_each_text(v_new)
             WHERE key LIKE 'id_%' ORDER BY key LIMIT 1)
        );
    ELSIF TG_OP = 'DELETE' THEN
        v_old := to_jsonb(OLD);
        v_new := NULL;
        v_id := COALESCE(
            v_old->>'id',
            (SELECT value FROM jsonb_each_text(v_old)
             WHERE key LIKE 'id_%' ORDER BY key LIMIT 1)
        );
    ELSIF TG_OP = 'INSERT' THEN
        v_old := NULL;
        v_new := to_jsonb(NEW);
        v_id := COALESCE(
            v_new->>'id',
            (SELECT value FROM jsonb_each_text(v_new)
             WHERE key LIKE 'id_%' ORDER BY key LIMIT 1)
        );
    END IF;

    -- Actor: intenta leer de variable de sesión (SET LOCAL app.current_user = 'username')
    BEGIN
        v_user := current_setting('app.current_user', true);
    EXCEPTION WHEN OTHERS THEN
        v_user := current_user;
    END;
    IF v_user IS NULL OR v_user = '' THEN v_user := current_user; END IF;

    INSERT INTO system_audit.audit_log
        (schema_name, table_name, operation, record_id, old_value, new_value, changed_by, register)
    VALUES
        (TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP, v_id, v_old, v_new, v_user, CURRENT_TIMESTAMP);

    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION system_audit.fn_audit_trigger() OWNER TO ronald;

