CREATE TABLE lead_service.lead (
    id_lead bigint CONSTRAINT lead_monthly_id_lead_not_null NOT NULL,
    id_cmpg bigint,
    id_src bigint CONSTRAINT lead_monthly_id_src_not_null NOT NULL,
    first_name character varying(100),
    last_name character varying(100),
    full_name text GENERATED ALWAYS AS (TRIM(BOTH FROM (((COALESCE(first_name, ''::character varying))::text || ' '::text) || (COALESCE(last_name, ''::character varying))::text))) STORED,
    phone character varying(50),
    email character varying(255),
    document_number character varying(50),
    raw_data jsonb DEFAULT '{}'::jsonb CONSTRAINT lead_monthly_raw_data_not_null NOT NULL,
    current_status_id bigint CONSTRAINT lead_monthly_current_status_id_not_null NOT NULL,
    assigned_user_id bigint,
    owner_user_id bigint,
    custody_user_id bigint,
    is_active boolean DEFAULT true CONSTRAINT lead_monthly_is_active_not_null NOT NULL,
    register timestamp with time zone DEFAULT CURRENT_TIMESTAMP CONSTRAINT lead_monthly_register_not_null NOT NULL,
    last_update timestamp with time zone DEFAULT CURRENT_TIMESTAMP CONSTRAINT lead_monthly_last_update_not_null NOT NULL
)
PARTITION BY RANGE (register);


