-- Name: lead_call_log; Type: TABLE; Schema: lead_service; Owner: ronald
--

CREATE TABLE lead_service.lead_call_log (
    id_call bigint NOT NULL,
    id_presale bigint NOT NULL,
    call_number smallint NOT NULL,
    company character varying(100),
    id_user bigint NOT NULL,
    call_type character varying(50) DEFAULT 'COMPANY_CALL'::character varying NOT NULL,
    result character varying(50),
    data_obtained jsonb DEFAULT '{}'::jsonb NOT NULL,
