    CONSTRAINT chk_phone_not_empty CHECK (((phone)::text <> ''::text))
);


ALTER TABLE lead_service.lead_pre_sale OWNER TO ronald;

--
-- Name: TABLE lead_pre_sale; Type: COMMENT; Schema: lead_service; Owner: ronald
--

COMMENT ON TABLE lead_service.lead_pre_sale IS 'El "papelito digital". Captura datos mínimos del cliente (teléfono, operador)
antes de abrir una venta formal. Se enriquece progresivamente en cada llamada
de compañía. Cuando el asesor decide avanzar, se convierte en sales_order
y los datos viajan pre-llenados. No genera porcentaje de cancelación.';


--
-- Name: COLUMN lead_pre_sale.tentative_offer; Type: COMMENT; Schema: lead_service; Owner: ronald
--

COMMENT ON COLUMN lead_service.lead_pre_sale.tentative_offer IS 'JSONB con la oferta que se va construyendo en las 3 llamadas:
{"company1": "Movistar", "offer1": "50€ fibra+2móviles",
 "company2": "Vodafone", "offer2": "45€ convergente",
 "company3": "Yoigo", "offer3": null, "accepted_company": "company2",
 "accepted_offer": "45€ convergente"}';


--
-- Name: lead_pre_sale_assignment; Type: TABLE; Schema: lead_service; Owner: ronald
--

CREATE TABLE lead_service.lead_pre_sale_assignment (
    id_assignment bigint NOT NULL,
    id_presale bigint NOT NULL,
    from_user_id bigint NOT NULL,
    to_user_id bigint NOT NULL,
    assignment_type character varying(50) DEFAULT 'ASSIST'::character varying NOT NULL,
    reason text,
    context_notes text,
    is_active boolean DEFAULT true NOT NULL,
    assigned_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    returned_at timestamp with time zone,
    register timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


ALTER TABLE lead_service.lead_pre_sale_assignment OWNER TO ronald;

--
-- Name: TABLE lead_pre_sale_assignment; Type: COMMENT; Schema: lead_service; Owner: ronald
--

COMMENT ON TABLE lead_service.lead_pre_sale_assignment IS 'Trazabilidad completa de derivaciones. ASSIST = Ronald ayuda a Chirlly
pero la venta sigue siendo de Chirlly (owner no cambia). TRANSFER = el
pre-sale cambia de dueño. COVER = cobertura por ausencia del asesor.';


