--
-- Name: v_applicants_passed; Type: VIEW; Schema: recruitment_service; Owner: ronald
--

CREATE VIEW recruitment_service.v_applicants_passed AS
 SELECT ap.id_applc,
    ap.id_doctyp,
    ap.document_number,
    ap.first_name,
    ap.last_name,
    ifp.pass_filter,
    ifp.register
   FROM ((recruitment_service.applicant ap
     LEFT JOIN recruitment_service.job_application jap ON ((ap.id_applc = jap.id_applc)))
     LEFT JOIN ( SELECT DISTINCT ON (interview_follow_up.id_jbapp) interview_follow_up.id_jbapp,
            interview_follow_up.pass_filter,
            interview_follow_up.register
           FROM recruitment_service.interview_follow_up
          ORDER BY interview_follow_up.id_jbapp, interview_follow_up.register DESC) ifp ON ((jap.id_jbapp = ifp.id_jbapp)))
  WHERE (ifp.pass_filter = true);


ALTER VIEW recruitment_service.v_applicants_passed OWNER TO ronald;

