--

CREATE TABLE sales_service.sales_form_field (
    id_fld bigint NOT NULL,
    id_form bigint NOT NULL,
    label character varying(200) NOT NULL,
    field_key character varying(100) NOT NULL,
    field_type character varying(50) NOT NULL,
    is_required boolean DEFAULT true NOT NULL,
    validation_regex character varying(255),
    options jsonb,
    order_index integer DEFAULT 0,
    is_active boolean DEFAULT true NOT NULL,
    validation_type character varying(50),
    source_table character varying(100),
    source_filter jsonb,
    placeholder character varying(200),
    help_text text,
    group_name character varying(100),
    depends_on_field bigint,
    depends_on_value text,
    is_data_real_flag boolean DEFAULT false NOT NULL
);


ALTER TABLE sales_service.sales_form_field OWNER TO ronald;

--
-- Name: COLUMN sales_form_field.validation_type; Type: COMMENT; Schema: sales_service; Owner: ronald
--

COMMENT ON COLUMN sales_service.sales_form_field.validation_type IS 'Tipo de validación:
IBAN_ES = IBAN español (ES + 22 dígitos)
DNI_ES  = DNI español (8 números + letra)
NIE_ES  = NIE (X/Y/Z + 7 números + letra)
CUPS_ENERGY = Código CUPS energía (ES + 20 chars)
PHONE_ES = Teléfono español (9 dígitos, empieza 6,7,8,9)
PROVINCE_ES = Desplegable de provincias españolas
CUSTOM = usa validation_regex de la columna existente';


