--
-- Name: sales_form_template; Type: TABLE; Schema: sales_service; Owner: ronald
--

CREATE TABLE sales_service.sales_form_template (
    id_form bigint NOT NULL,
    id_cmpg bigint NOT NULL,
    name character varying(150),
    description text,
    register timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    id_stage bigint,
    form_order smallint DEFAULT 1 NOT NULL,
    is_primary boolean DEFAULT true NOT NULL,
    allows_partial boolean DEFAULT true NOT NULL,
    min_completion_pct smallint DEFAULT 100 NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);


ALTER TABLE sales_service.sales_form_template OWNER TO ronald;

--
-- Name: COLUMN sales_form_template.is_primary; Type: COMMENT; Schema: sales_service; Owner: ronald
--

COMMENT ON COLUMN sales_service.sales_form_template.is_primary IS 'En etapas con 2 formularios (ficha 1 y ficha 2), el formulario primario
es el que determina si se puede avanzar. El secundario se puede llenar
parcialmente pero no bloquea el flujo.';


--
-- Name: COLUMN sales_form_template.min_completion_pct; Type: COMMENT; Schema: sales_service; Owner: ronald
--

COMMENT ON COLUMN sales_service.sales_form_template.min_completion_pct IS 'Porcentaje mínimo de campos requeridos completos para habilitar el avance.
100 = todos los campos requeridos deben estar llenos.
80 = puede avanzar con hasta 20% de campos opcionales vacíos.';


