    id_lead bigint CONSTRAINT sales_order_monthly_id_lead_not_null NOT NULL,
    id_cmpg bigint CONSTRAINT sales_order_monthly_id_cmpg_not_null NOT NULL,
    id_user bigint CONSTRAINT sales_order_monthly_id_user_not_null NOT NULL,
    owner_user_id bigint,
    custody_user_id bigint,
    id_status bigint,
    id_substatus bigint,
    currency_code character(3) DEFAULT 'EUR'::bpchar,
    commission_currency character(3) DEFAULT 'PEN'::bpchar,
    status character varying(50) DEFAULT 'PENDING_VALIDATION'::character varying,
    sales_date timestamp with time zone DEFAULT CURRENT_TIMESTAMP CONSTRAINT sales_order_monthly_sales_date_not_null NOT NULL,
    total_products integer DEFAULT 0 CONSTRAINT sales_order_monthly_total_products_not_null NOT NULL,
    total_value numeric(12,2),
    is_alternate boolean DEFAULT false CONSTRAINT sales_order_monthly_is_alternate_not_null NOT NULL,
    register timestamp with time zone DEFAULT CURRENT_TIMESTAMP CONSTRAINT sales_order_monthly_register_not_null NOT NULL,
    last_update timestamp with time zone DEFAULT CURRENT_TIMESTAMP CONSTRAINT sales_order_monthly_last_update_not_null NOT NULL
)
PARTITION BY RANGE (register);


ALTER TABLE sales_service.sales_order OWNER TO ronald;

--
-- Name: sales_order_approval; Type: TABLE; Schema: sales_service; Owner: ronald
--

CREATE TABLE sales_service.sales_order_approval (
    id_approval bigint NOT NULL,
    id_order bigint NOT NULL,
    approval_type character varying(100) NOT NULL,
    status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    requested_by bigint NOT NULL,
    approved_by bigint,
    rejection_reason text,
    approval_reason text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    expires_at timestamp with time zone,
    register timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    resolved_at timestamp with time zone,
    CONSTRAINT chk_approval_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying])::text[])))
);


ALTER TABLE sales_service.sales_order_approval OWNER TO ronald;

--
-- Name: TABLE sales_order_approval; Type: COMMENT; Schema: sales_service; Owner: ronald
--

COMMENT ON TABLE sales_service.sales_order_approval IS 'Registro de aprobaciones de excepción. Cuando un supervisor autoriza
una baja por alta o un cambio de compañía en clawback, queda registrado
aquí con todos los detalles para trazabilidad y reportes de gestión.
El sistema bloquea la acción hasta que haya un registro APPROVED.';


